const char* key_data = key.data();
size_t key_size = key.size();
const char* value_data = value.data();
size_t value_size = value.size();

if (*counter % restart_interval == 0) {
    restarts->push_back(static_cast<uint32_t>(buffer->size()));
    *last_key = key.ToString();
    PutVarint32(buffer, key_size);
    PutVarint32(buffer, value_size);
    buffer->append(key_data, key_size);
    buffer->append(value_data, value_size);
} else {
    size_t shared = 0;
    const size_t min_len = std::min(last_key->size(), key_size);
    while (shared < min_len && (*last_key)[shared] == key_data[shared]) {
        ++shared;
    }
    size_t non_shared = key_size - shared;
    PutVarint32(buffer, shared);
    PutVarint32(buffer, non_shared);
    PutVarint32(buffer, value_size);
    buffer->append(key_data + shared, non_shared);
    buffer->append(value_data, value_size);
    *last_key = key.ToString();
}
++(*counter);
// END_CODE

